"""
Batch endpoint-aligned adaptive filtering.

The returned element i estimates input element i + window_size - 1.
"""
import numpy as np


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float).reshape(-1)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return np.convolve(x, np.ones(window_size, dtype=float) / window_size, mode="valid")


def _robust_scale(values):
    values = np.asarray(values, dtype=float).reshape(-1)
    if values.size == 0:
        return 0.0
    med = np.median(values)
    return float(1.4826 * np.median(np.abs(values - med)))


def _fallback_smoother(x, window_size):
    x = np.asarray(x, dtype=float)
    n = len(x)
    if n < 3:
        return x.copy()
    k = min(max(5, 2 * (window_size // 2) + 1), n if n % 2 else n - 1)
    if k < 3:
        return x.copy()
    try:
        from scipy.signal import savgol_filter
        return np.asarray(
            savgol_filter(x, k, min(2, k - 1), mode="interp"), dtype=float
        )
    except Exception:
        z = np.pad(x, (k // 2, k // 2), mode="edge")
        return np.convolve(z, np.ones(k) / k, mode="valid")[:n]


def _filled_signs(y):
    d = np.diff(y)
    s = np.sign(d).astype(float)
    if not s.size:
        return s
    for i in range(1, len(s)):
        if s[i] == 0:
            s[i] = s[i - 1]
    for i in range(len(s) - 2, -1, -1):
        if s[i] == 0:
            s[i] = s[i + 1]
    return s


def _has_large_jump(x, left, right, jump_size):
    return right > left and bool(
        np.any(np.abs(np.diff(x[left:right + 1])) >= jump_size)
    )


def _cancel_weak_excursions(y, reference, sigma):
    y = np.asarray(y, dtype=float).copy()
    reference = np.asarray(reference, dtype=float)
    if len(y) < 7:
        return y

    residual = _robust_scale(reference - y)
    slope_scale = _robust_scale(np.diff(y))
    tau = max(0.35 * residual, 0.08 * slope_scale, 1e-12)
    jump_size = max(5.0 * sigma, 6.0 * tau, 1e-12)

    for _ in range(2):
        s = _filled_signs(y)
        extrema = np.flatnonzero(s[1:] != s[:-1]) + 1
        if extrema.size < 3:
            break
        changed = False
        for j in range(1, len(extrema) - 1):
            left, center, right = map(int, extrema[j - 1:j + 2])
            if right - left < 2:
                continue
            if min(abs(y[center] - y[left]), abs(y[right] - y[center])) >= 1.25 * tau:
                continue
            raw_left = abs(reference[center] - reference[left])
            raw_right = abs(reference[right] - reference[center])
            if min(raw_left, raw_right) >= 2.0 * tau:
                continue
            if _has_large_jump(reference, left, right, jump_size):
                continue
            y[left:right + 1] = np.linspace(y[left], y[right], right - left + 1)
            changed = True
        if not changed:
            break
    return y


def _fused_curvature_reconstruction(x, sigma):
    x = np.asarray(x, dtype=float).reshape(-1)
    n = len(x)
    if n < 4:
        return x.copy()

    try:
        from scipy.linalg import solve_banded

        robust = max(float(sigma), 1e-8)
        spread = float(np.percentile(x, 75) - np.percentile(x, 25))
        jump = max(5.0 * robust, 0.18 * spread, 1e-8)
        cuts = []
        for j in np.flatnonzero(np.abs(np.diff(x)) >= jump) + 1:
            left = x[max(0, j - 4):j]
            right = x[j:min(n, j + 4)]
            if left.size and right.size and abs(np.median(right) - np.median(left)) >= jump:
                cuts.append(int(j))

        def fit_segment(v):
            m = len(v)
            if m < 4:
                return v.copy()
            best, best_cost = None, np.inf
            diag_penalty = np.r_[
                [1.0, 5.0], np.full(max(0, m - 4), 6.0), [5.0, 1.0]
            ][:m]
            off_penalty = np.r_[
                [-2.0], np.full(max(0, m - 3), -4.0), [-2.0]
            ][:m - 1]
            for multiplier in (0.25, 0.6, 1.2, 2.4):
                lam = multiplier * robust * robust * m
                y = v.copy()
                for _ in range(3):
                    r = v - y
                    scale = max(_robust_scale(r), robust * 0.25)
                    w = np.minimum(1.0, 1.5 * scale / (np.abs(r) + 1e-12))
                    ab = np.zeros((5, m), dtype=float)
                    ab[2] = w + lam * diag_penalty
                    ab[1, 1:] = lam * off_penalty
                    ab[3, :-1] = lam * off_penalty
                    ab[0, 2:] = lam
                    ab[4, :-2] = lam
                    y = solve_banded((2, 2), ab, w * v)
                reversals = np.count_nonzero(np.diff(np.sign(np.diff(y))) != 0)
                cost = np.median(np.abs(v - y)) / robust + 0.035 * reversals
                if np.isfinite(cost) and cost < best_cost:
                    best, best_cost = y.copy(), cost
            return v.copy() if best is None else best

        result = np.empty_like(x)
        bounds = [0] + cuts + [n]
        for left, right in zip(bounds[:-1], bounds[1:]):
            result[left:right] = fit_segment(x[left:right])
        return result if np.all(np.isfinite(result)) else x.copy()
    except Exception:
        return x.copy()


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float).reshape(-1)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )

    if not np.all(np.isfinite(x)):
        finite = x[np.isfinite(x)]
        fill = float(np.median(finite)) if finite.size else 0.0
        x = np.nan_to_num(x, nan=fill, posinf=fill, neginf=fill)

    if len(x) < 7:
        return _fallback_smoother(x, window_size)[window_size - 1:]

    sigma = max(_robust_scale(np.diff(x)) / np.sqrt(2.0), 1e-12)
    smooth = _fused_curvature_reconstruction(x, sigma)
    if smooth.shape != x.shape or not np.all(np.isfinite(smooth)):
        smooth = _fallback_smoother(x, window_size)
    smooth = _cancel_weak_excursions(smooth, x, sigma)
    return np.asarray(smooth, dtype=float)[window_size - 1:]


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean += 0.1 * t * np.sin(0.2 * t)
    clean += np.cumsum(rng.randn(length) * 0.05)
    return clean + rng.normal(0, noise_level, length), clean


def run_signal_processing(
    noisy_signal=None, signal_length=1000, noise_level=0.3, window_size=20
):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered = process_signal(noisy_signal, window_size, "enhanced")
    if clean_signal is None:
        return {
            "filtered_signal": filtered,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered),
        }

    delay = window_size - 1
    clean = clean_signal[delay:]
    noisy = noisy_signal[delay:]
    m = min(len(filtered), len(clean))
    filtered, clean, noisy = filtered[:m], clean[:m], noisy[:m]
    corr = (
        float(np.corrcoef(filtered, clean)[0, 1])
        if m > 1 and np.std(filtered) > 0 and np.std(clean) > 0
        else 0.0
    )
    before = np.var(noisy - clean)
    after = np.var(filtered - clean)
    reduction = float((before - after) / before) if before > 0 else 0.0
    return {
        "filtered_signal": filtered,
        "clean_signal": clean,
        "noisy_signal": noisy,
        "correlation": corr,
        "noise_reduction": reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

